head.script:
scwin.onpageload = function() {
    scwin.setData();
};
scwin.onpageunload = function() {};
scwin.setData = function() {
    var jsonData = [{
        "label": "a1",
        "value": "a1",
        "depth": "1"
    }, {
        "label": "a1-1",
        "value": "a1-1",
        "depth": "2"
    }, {
        "label": "a1-1-1",
        "value": "a1-1-1",
        "depth": "3"
    }, {
        "label": "a1-1-2",
        "value": "a1-1-2",
        "depth": "3"
    }, {
        "label": "a1-1-3",
        "value": "a1-1-3",
        "depth": "3"
    }, {
        "label": "a1-2",
        "value": "a1-2",
        "depth": "2"
    }, {
        "label": "a1-3",
        "value": "a1-3",
        "depth": "2"
    }, {
        "label": "b1",
        "value": "b1",
        "depth": "1"
    }, {
        "label": "b1-1",
        "value": "b1-1",
        "depth": "2"
    }, {
        "label": "b1-2",
        "value": "b1-2",
        "depth": "2"
    }, {
        "label": "b1-3",
        "value": "b1-3",
        "depth": "2"
    }];
    jsonData = jsonData.concat(jsonData).concat(jsonData);
    jsonData = jsonData.concat(jsonData).concat(jsonData);
    jsonData = jsonData.concat(jsonData).concat(jsonData);
    dataList1.setJSON(jsonData);
};
scwin.trigger1_onclick = function() {
    treeview1.spanNode({
        depth: 1
    }, false);
    treeview2.spanNode({
        depth: 1
    }, false);
}
scwin.checkVal = function() {
    var className1 = WebSquare.wUnit.getDomById($p.id + 'treeview2_node_1').children[0].className;
    return className1.indexOf("treeview_icon_open") > 0;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
